        letter-spacing: 2px;
        margin: 0;
    }

    .masthead .linha2 {
        font-family: "Arial Black", Impact, sans-serif;
        font-weight: bold;
        font-size: 86px;
        line-height: 0.95;
        letter-spacing: 4px;
        margin: 6px 0 4px 0;
    }

    .masthead .linha3 {
        font-family: "Arial Black", Impact, sans-serif;
        font-weight: bold;
        font-size: 30px;
        letter-spacing: 3px;
        margin: 0 0 8px 0;
    }

    hr.grossa {
        border: none;
        border-top: 3px solid #000;
        margin: 4px 0 2px 0;
    }

    hr.fina {
        border: none;
        border-top: 1px solid #000;
        margin: 2px 0 6px 0;
    }

    .cabecalho {
        display: flex;
        justify-content: space-between;
        font-variant: small-caps;
        font-size: 15px;
        padding: 2px 6px;
    }

    .cabecalho .centro {
        font-variant: normal;
        font-size: 18px;
        letter-spacing: 1px;
    }

    .colunas {
        display: flex;
        margin-top: 10px;
    }

    .coluna {
        width: 50%;
        text-align: justify;
        font-size: 14.5px;
        line-height: 1.25;
    }

    .coluna.esq {
        padding-right: 18px;
        border-right: 1px solid #000;
    }

    .coluna.dir {
        padding-left: 18px;
    }

    .coluna p {
        margin: 0;
        text-indent: 1.6em;
    }

    .titulo-secao {
        font-family: "Arial Black", Impact, sans-serif;
        font-size: 30px;
        text-align: center;
        letter-spacing: 1px;
        margin: 0 0 4px 0;
    }

    .risco-curto {
        width: 130px;
        border: none;
        border-top: 1px solid #000;
        margin: 6px auto 14px auto;
    }

    .risco-medio {
        width: 180px;
        border: none;
        border-top: 1px solid #000;
        margin: 26px auto 26px auto;
    }

    .decreto {
        font-family: "Arial Black", Impact, sans-serif;
        font-size: 22px;
