        letter-spacing: 3px;
        margin: 12px 0 6px 0;
    }

    .data-decreto {
        text-align: center;
        font-variant: small-caps;
        font-size: 15px;
        margin-bottom: 14px;
    }

    .ementa {
        font-style: italic;
        text-align: justify;
        margin-bottom: 14px;
        text-indent: 0;
    }

    .assinatura {
        text-align: left;
        margin-top: 10px;
        margin-left: 1.6em;
        font-size: 17px;
        letter-spacing: 1px;
    }

    .assinatura.menor {
        font-size: 14px;
        font-variant: small-caps;
        letter-spacing: 1px;
    }

    .titulo-clausulas {
        text-align: center;
        font-size: 24px;
        line-height: 1.15;
        margin: 0 0 18px 0;
    }

    .numeral {
        text-align: center;
        font-size: 16px;
        letter-spacing: 2px;
